    "enunciado": "O professor Alfred Chandler disse que a “estrutura segue a estratégia”. Se o novo servidor público quer entender mais a nova organização e sua respectiva estratégia, é recomendável analisar sua estrutura. A estrutura organizacional que apresenta alta amplitude de controle é a:",
