    "modulo_id": 3,
    "enunciado": "Com relação aos Deputados Federais e Senadores, nos termos da Constituição Federal, é correto afirmar:",
    "alternativa_a": "Não perderá o mandato o Deputado ou Senador investido no cargo de Ministro de Estado, Governador de Território, Secretário de Estado, do Distrito Federal, de Território, de Prefeitura de Capital ou chefe de missão diplomática temporária.",
    "alternativa_b": "A incorporação às Forças Armadas de Deputados e Senadores, embora militares em tempo de guerra, não dependerá de prévia licença da Casa respectiva.",
    "alternativa_c": "Os Deputados e os Senadores serão obrigados a testemunhar sobre informações recebidas ou prestadas em razão do exercício do mandato, bem como sobre as pessoas que lhes confiaram ou deles receberam informações.",
    "alternativa_d": "Perderá o mandato o Deputado ou o Senador que deixar de comparecer, em cada sessão legislativa, à quarta parte das sessões ordinárias da Casa a que pertencer, salvo licença ou missão por esta autorizada.",
    "alternativa_e": "As imunidades de Deputados ou Senadores subsistirão durante o estado de sítio, só podendo ser suspensas mediante o voto de um terço dos membros da Casa respectiva, nos casos de atos praticados fora do recinto do Congresso Nacional, que sejam incompatíveis com a execução da medida.",
