    "enunciado": "Tendo como base as disposições previstas no Código Penal e na legislação extravagante, bem como os posicionamentos doutrinários e jurisprudenciais, marque a alternativa incorreta.",
    "alternativa_a": "Nos casos em que se aplica a Lei n. 13.654/2018 (abolitio da causa de aumento de pena da arma branca), é possível a valoração do emprego de arma branca, no crime de roubo, como circunstância judicial desabonadora.",
    "alternativa_b": "O pagamento de salário não configura apropriação ou desvio de verba pública, previstos pelo art. 1º, I, do Decreto-Lei n. 201/1967, pois a remuneração é devida, ainda que questionável a contratação de parentes do Prefeito.",
    "alternativa_c": "Não se configura como crime de peculato-desvio o fomento econômico de candidatura à reeleição por Governador de Estado com o patrimônio de empresas estatais.",
