    "alternativa_c": "A obtenção de lucro fácil e a cobiça constituem elementares dos tipos de concussão e corrupção passiva (arts. 316 e 317 do CP), sendo indevido utilizá-las para aumentar a pena-base alegando que os “motivos do crime” (circunstância judicial do art. 59 do CP) seriam desfavoráveis.",
