    "enunciado": "Essa é uma qualificação dada à autarquia ou fundação que, por meio do contrato de gestão com o órgão da Administração Direta a que esteja vinculada, amplia sua autonomia para a melhoria da eficiência e redução de custos. O enunciado da questão se referiu ao conceito de",
