    "modulo_id": 10,
    "enunciado": "Sobre as regras aplicáveis aos servidores públicos, assinale a alternativa certa.",
    "alternativa_a": "A única hipótese de perda dos cargos efetivos é por meio de processo judicial com decisão transitada em julgado.",
    "alternativa_b": "Os cargos em comissão são exercidos exclusivamente por servidores ocupantes de cargo efetivo.",
    "alternativa_c": "É hipótese de perda de cargo do servidor estável quando a despesa com pessoal ativo e inativo da União, dos estados, do Distrito Federal e dos municípios exceder os limites estabelecidos em lei complementar.",
    "alternativa_d": "Em regra, é permitida a acumulação remunerada de cargos públicos.",
