    "alternativa_b": "A intersecção entre desenvolvimento urbano e redução da violência deve enfatizar, portanto o papel fundamental das cidades na prevenção por intermédio – da promoção da convivência, da interação e da inclusão social; da utilização e ocupação dos espaços públicos e do pleno exercício da cidadania.",
    "alternativa_c": "A intersecção entre desenvolvimento urbano e redução da violência, deve enfatizar, portanto, o papel fundamental das cidades na prevenção por intermédio – da promoção da convivência, da interação e da inclusão social, da utilização e ocupação dos espaços públicos; e do pleno exercício da cidadania. Escrivão e Agente Substituto",
    "alternativa_d": "A intersecção, entre desenvolvimento urbano e redução da violência, deve enfatizar, portanto, o papel fundamental das cidades na prevenção por intermédio: da promoção da convivência, da interação e da inclusão social, da utilização e ocupação dos espaços públicos e do pleno exercício da cidadania.",
    "alternativa_e": "A intersecção entre desenvolvimento urbano e redução da violência deve enfatizar, portanto, o papel fundamental das cidades na prevenção por intermédio – da promoção da convivência; da interação e da inclusão social; da utilização e ocupação dos espaços públicos; e do pleno exercício da cidadania. TEXTO II Texto para as questões de 11 a 20. O Ministério da Justiça e Segurança Pública está entregando às Secretarias de Segurança Pública dos 26 estados e do Distrito Federal um novo lote de equipamentos destinados ao combate ao crime. A fim de concretizar esse objetivo, a iniciativa faz parte de um convênio de cooperação que representantes das 27 unidades da federação assinaram com o ministério. A entrega simbólica de 1.660 carabinas ocorreu hoje (14), em uma cerimônia na sede do ministério, em Brasília. Presidente do Colégio Nacional de Secretários de Segurança Pública, o responsável pela pasta no estado do Tocantins, Cristiano Sampaio, representou os demais secretários. Segundo o referido ministério, investiram-se R$ 9,7 milhões na compra das armas. “Para estados com menos recursos, estes equipamentos têm uma importância maior e fortalecem a segurança pública como um todo”, disse Sampaio ao defender a importância da integração entre os estados e o governo federal e a necessidade de repactuação da divisão de recursos financeiros para o setor. “A segurança pública passa pela discussão da partilha dos recursos. Além disso, tem um ditado que diz que ‘em casa que falta pão, todo mundo reclama e ninguém tem razão’. Precisamos reconhecer que temos tido um maior aporte de recursos para a área, com o Fundo Nacional de Segurança Pública e emendas parlamentares trazendo um maior volume de recursos do que tínhamos, mas também é preciso reconhecer que isso ainda é muito pouco diante dos custos”, comentou o secretário. Disponível em: <https://agenciabrasil.ebc.com.br/geral/noticia/2020-08/ministerio-entrega-r-97-milhoes-em-equipamentos-de-seguranca>",
    "alternativa_correta": "e",
