    "modulo_id": 7,
    "enunciado": "Ricardo nasceu na Alemanha no período em que seu pai, de nacionalidade brasileira, ali residia em caráter permanente. À luz da sistemática constitucional, é correto afirmar que Ricardo:",
    "alternativa_a": "será cidadão brasileiro caso venha a residir no território brasileiro e opte por esta nacionalidade até os 18 anos.",
