    "enunciado": "De acordo com o Estatuto da Pessoa com Deficiência (Lei n. 13.146/2015), assinale a alternativa incorreta.",
    "alternativa_a": "Considera-se pessoa com deficiência aquela que tem impedimento de curto ou longo prazo, considerado apenas de natureza física, mental ou intelectual, o qual, em interação com uma ou mais barreiras, pode obstruir sua participação plena e efetiva na sociedade em igualdade de condições com as demais pessoas.",
    "alternativa_b": "Toda pessoa com deficiência tem direito à igualdade de oportunidades com as demais pessoas e não sofrerá nenhuma espécie de discriminação.",
    "alternativa_c": "Em situações de risco, emergência ou estado de calamidade pública, a pessoa com deficiência será considerada vulnerável, devendo o poder público adotar medidas para sua proteção e segurança.",
    "alternativa_d": "A pessoa com deficiência somente será atendida sem seu consentimento prévio, livre e esclarecido em casos de risco de morte e de emergência em saúde, resguardado seu superior interesse e adotadas as salvaguardas legais cabíveis.",
    "alternativa_e": "Os serviços do SUS e do SUAS deverão promover ações articuladas para garantir à pessoa com deficiência e sua família a aquisição de informações, orientações e formas de acesso às políticas públicas disponíveis, com a finalidade de propiciar sua plena participação social. NOÇÕES DE MEDICINA LEGAL LAÉCIO CARNEIRO",
