    "alternativa_d": "por corolário",
    "alternativa_e": "com efeito Texto 2 \u0001 A economia global deve crescer 4% em 2021 depois de encolher 4,3% em 2020, disse o Banco Mundial nesta terça-feira 5, embora tenha alertado que o aumento das infecções por Covid-19 e os atrasos na distribuição das vacinas podem limitar a recuperação econômica e financeira para apenas 1,6% neste ano. \u0001 A previsão semestral do Banco Mundial mostrou que o colapso na atividade devido à pandemia do novo coronavírus foi ligeiramente menos grave do que o previsto anteriormente, mas a recuperação também estava mais moderada e ainda sujeita a consideráveis riscos negativos. \u0001 “A perspectiva de curto prazo permanece altamente incerta”, disse o Banco em um comunicado. “Um cenário negativo em que as infecções continuem a aumentar e o lançamento de uma vacina seja adiado podem limitar a expansão global a 1,6% em 2021.” \u0001Com o controle bem-sucedido da pandemia e um processo de vacinação mais rápido, o crescimento global pode acelerar para quase 5%, disse o banco em seu último relatório de Perspectivas Econômicas Globais. \u0001 Mais de 85 milhões de pessoas foram infectados pelo novo coronavírus, e quase 1,85 milhão morreu desde que os primeiros casos foram identificados na China, em dezembro de 2019. Apesar disso, pelo menos 40% da população mundial não acreditam ainda na ação letal do vírus. \u0001 Internet, <https://agorarn.com.br/ultimas/banco-mundial-prevesalto-de-4-no-pib-global-em-2021/>, com adaptações.",
