    "enunciado": "“... embora tenha alertado que o aumento das infecções por Covid-19 e os atrasos na distribuição das vacinas podem limitar a recuperação para apenas 1,6% neste ano”. Nessa frase do texto 2, empregou-se corretamente o presente do subjuntivo do verbo “ter” (tenha). Assinale a frase em que a forma do futuro do subjuntivo destacado está errada.",
