    "enunciado": "Douglas McGregor foi um autor behaviorista que se preocupou em comparar dois estilos distintos de administrar, aos quais deu o nome de Teoria X e Teoria Y, e que levavam em consideração o comportamento humano nas organizações. Nesse sentido, analise as afirmativas a seguir. I – O ser humano da Teoria X é indolente e egocêntrico. Falta-lhe ambição e trabalha o mínimo possível. II – O ser humano da Teoria Y é naturalmente resistente às mudanças, mas tem potencial para assumir desafios. III – Em ambos os casos (Teoria X e Teoria Y) o desempenho do ser humano varia em função dos incentivos financeiros. Assinale:",
