    "enunciado": "Assinale a opção incorreta em relação ao entendimento do STF.",
    "alternativa_a": "Só é lícito o uso de algemas em casos de resistência e de fundado receio de fuga ou de perigo à integridade física própria ou alheia, por parte do preso ou de terceiros, justificada a excepcionalidade por escrito, sob pena de responsabilidade disciplinar, civil e penal do agente ou da autoridade e de nulidade da prisão ou do ato processual a que se refere, sem prejuízo da responsabilidade civil do Estado.",
    "alternativa_b": "O policial militar que, a pretexto de exercer atividade de repressão criminal em nome do Estado, inflige, mediante desempenho funcional abusivo, danos físicos a menor momentaneamente sujeito ao seu poder de coerção, valendo-se desse meio executivo para intimidá-lo e coagi-lo à confissão de determinado delito, pratica, inequivocamente, o crime de tortura.",
