    "enunciado": "Assinale a opção incorreta em relação aos direitos políticos.",
    "alternativa_a": "O alistamento eleitoral e o voto são obrigatórios para os maiores de dezoito anos.",
    "alternativa_b": "Não podem alistar-se como eleitores os estrangeiros e, durante o período do serviço militar obrigatório, os conscritos.",
    "alternativa_c": "O Presidente da República, os Governadores de Estado e do Distrito Federal, os Prefeitos e quem os houver sucedido, ou substituído no curso dos mandatos poderão ser reeleitos para um único período subsequente.",
