    "modulo_id": 7,
    "enunciado": "Assinale a opção incorreta sobre a segurança pública.",
    "alternativa_a": "Às polícias civis, dirigidas por delegados de polícia de carreira, incumbem, ressalvada a competência da União, as funções de polícia judiciária e a apuração de infrações penais, exceto as militares.",
