    "enunciado": "Assinale a alternativa correta acerca do erro de tipo.",
    "alternativa_a": "Um agente, com a livre intenção de matar desafeto seu, disparou na direção deste, mas atingiu fatalmente pessoa diversa, que se encontrava próxima ao seu alvo, sendo assim, configurou-se o erro sobre a pessoa e o agente responderá criminalmente como se tivesse atingido a pessoa visada.",
