    "modulo_id": 1,
    "enunciado": "Quanto aos crimes contra a dignidade sexual, assinale a alternativa correta.",
    "alternativa_a": "O crime de estupro não admite retratação nem perdão pela vítima, cabendo ao Ministério Público oferecer a denúncia no prazo de cinco dias, estando o investigado solto.",
    "alternativa_b": "Flávia, de quatorze anos de idade, acusa Sebastian, de dezoito anos de idade, de ter praticado crime de natureza sexual consistente em conjunção carnal forçada no dia do último aniversário de Flávia. Sebastian, contudo, alega que o ato sexual foi consentido. Caso fique comprovado o consentimento de Flávia para a prática do ato sexual, a conduta de Sebastian será considerada atípica.",
    "alternativa_c": "Médice foi flagrado, em operação da Polícia Civil do Estado do Rio Grande do Norte, submetendo uma adolescente a exploração sexual em rodovia estadual. Nessa situação, Médice poderá não responder pelo crime se comprovar o consentimento da menor.",
    "alternativa_d": "O crime de importunação sexual (art. 215-A, CP) consiste em praticar contra menor de 18 (dezoito) anos e sem a sua anuência ato libidinoso com o objetivo de satisfazer a própria lascívia ou a de terceiro.",
    "alternativa_e": "A prática de passar as mãos nas coxas e seios da vítima menor de 14 anos, por dentro de sua roupa, não pode ser tipificado como crime de estupro de vulnerável (art. 217-A do Código Penal), haja vista que não houve a conjunção carnal.",
