    "modulo_id": 1,
    "enunciado": "Sobre os crimes contra o patrimônio, julgue os itens seguintes Verdadeiros (V) ou Falsos (F) e assinale a alternativa correta. I – Pedro, com vinte e dois anos de idade, e Paulo, com vinte anos de idade, foram denunciados pela prática de furto contra Ana. A defesa de Pedro alegou inimputabilidade. Paulo confessou o crime, tendo afirmado que escolhera a vítima porque, além de idosa, ela era sua tia. Sendo assim, a ação penal será pública condicionada a representação. II – No crime contra o patrimônio em que a coisa é subtraída e a violência é praticada com a intenção de matar a vítima, sem que esta chegue a morrer, a conduta é tipificada como tentativa de latrocínio. III – Conforme jurisprudência dominante no STJ, nos crimes de furto e roubo (arts. 155 e 157 do CP) a consumação do fato típico somente ocorre com a posse mansa e pacífica, o que não se verifica no caso de perseguição imediata do agente e recuperação da coisa subtraída.",
