    "modulo_id": 9,
    "enunciado": "Segundo a Lei n. 7.210/1984 (Lei de Execução Penal), prática de fato previsto como crime doloso constitui falta grave e, quando ocasionar subversão da ordem ou disciplina internas, sujeitará o preso provisório, ou condenado, nacional ou estrangeiro, sem prejuízo da sanção penal, ao regime disciplinar diferenciado, com as seguintes características:",
