    "modulo_id": 9,
    "enunciado": "Assinale a alternativa correta de acordo com as previsões expressas da Lei n. 8.072/1990.",
    "alternativa_a": "O crime de comércio ilegal de armas de fogo é considerado hediondo.",
    "alternativa_b": "Os crimes hediondos, a prática da tortura, o tráfico ilícito de entorpecentes e drogas afins e o terrorismo são insuscetíveis de anistia, graça, indulto, fiança e liberdade provisória.",
