    "modulo_id": 9,
    "enunciado": "A respeito da Lei n. 13.869/2019 (Lei de Abuso de Autoridade), assinale a alternativa correta.",
    "alternativa_a": "A divergência na interpretação de lei ou na avaliação de fatos e provas configura abuso de autoridade.",
    "alternativa_b": "As condutas descritas nesta Lei constituem crime de abuso de autoridade somente quando praticadas pelo agente com a finalidade específica de prejudicar outrem ou beneficiar a si mesmo ou a terceiro, ou, ainda, por mero capricho ou satisfação pessoal.",
    "alternativa_c": "Os crimes previstos nesta Lei são de ação penal pública condicionada.",
