    "enunciado": "A respeito da Lei Federal n. 13.964/2019 (Pacote Anticrime), assinale a alternativa correta.",
    "alternativa_a": "Esta Lei aperfeiçoa a legislação penal e processual penal.",
    "alternativa_b": "Transitada em julgado a sentença condenatória, a multa será executada perante o juiz da execução fiscal e será considerada dívida de valor, aplicáveis as normas relativas à dívida ativa da Fazenda Pública, inclusive no que concerne às causas interruptivas e suspensivas da prescrição.",
    "alternativa_c": "Na hipótese de condenação por infrações às quais a lei comine pena máxima superior a 8 (oito) anos de reclusão, poderá ser decretada a perda, como produto ou proveito do crime, dos bens correspondentes à diferença entre o valor do patrimônio do condenado e aquele que seja compatível com o seu rendimento lícito.",
    "alternativa_d": "O crime de estelionato somente se procede mediante queixa.",
