    "enunciado": "De acordo com Lei Orgânica e o Estatuto da Polícia Civil do Estado do Rio Grande do Norte, assinale a alternativa correta.",
    "alternativa_a": "Ocorrendo empate na classificação, tanto por Merecimento quanto por Antiguidade, terá precedência, sucessivamente, o candidato que tiver mais tempo de efetivo exercício na Classe, no cargo e, por fim, melhor classificação final do concurso de ingresso na carreira, referente ao cargo em que estiver ocupando.",
