    "modulo_id": 10,
    "enunciado": "De acordo com a Lei n. 8.666/1993, que institui normas para licitações e contratos da Administração Pública, assinale a associação incorreta.",
    "alternativa_a": "Nas licitações para a execução de obras e serviços, quando for adotada a modalidade de execução de empreitada por preço global, a Administração deverá fornecer obrigatoriamente, junto com o edital, todos os elementos e informações necessários para que os licitantes possam elaborar suas propostas de preços com total e completo conhecimento do objeto da licitação.",
    "alternativa_b": "Quando todos os licitantes forem inabilitados ou todas as propostas forem desclassificadas, a Administração poderá fixar aos licitantes o prazo de oito dias úteis para a apresentação de nova documentação ou de outras propostas escoimadas das causas referidas neste artigo, facultada, no caso de convite, a redução deste prazo para três dias úteis.",
    "alternativa_c": "Caso seja conveniente para o interesse público, a Administração poderá celebrar o contrato com preterição da ordem de classificação das propostas ou, caso não haja mais licitantes suficientes, com terceiros estranhos ao procedimento licitatório.",
    "alternativa_d": "No caso de convite, a Comissão de licitação, excepcionalmente, nas pequenas unidades administrativas e em face da exiguidade de pessoal disponível, poderá ser substituída por servidor formalmente designado pela autoridade competente.",
    "alternativa_e": "No caso de concurso, o julgamento será feito por uma comissão especial integrada por pessoas de reputação ilibada e reconhecido conhecimento da matéria em exame, servidores públicos ou não.",
