    "modulo_id": 10,
    "enunciado": "Sobre os assuntos afetos à Medicina Legal, marque a alternativa correta.",
    "alternativa_a": "O laudo, espécie de auto, é redigido pelo escrivão ou servidor administrativo, quando ditado pelo perito legista.",
    "alternativa_b": "A cronotanatognose permite estimar o tempo de morte pelos livores, pelo algor e pelo rigor cadavérico, por exemplo.",
