    "modulo_id": 4,
    "enunciado": "“Parece paradoxal que, no início deste milênio, durante o que chamamos com orgulho de “era da ciência”, tantos ainda acreditem em profecias de fim de mundo. Quem não se lembra do bug do milênio ou da enxurrada de absurdos ditos todos os dias sobre a previsão maia de fim de mundo no ano 2012?” Assinale a opção que indica a função do termo destacado:",
    "alternativa_a": "Anafórico.",
