    "modulo_id": 6,
    "enunciado": "A Diretora-Geral de uma delegacia de polícia afirmou que seu tempo é quase todo destinado a questões relacionadas à orçamentação das atividades da sua delegacia, bem como à programação do trabalho de seus funcionários, distribuindo tarefas e definindo atribuições. A Diretora-geral desempenha, em especial, um papel:",
