    "modulo_id": 6,
    "enunciado": "A departamentalização é um método de subdivisão do trabalho e dos trabalhadores em unidades organizacionais distintas. Uma desvantagem da departamentalização funcional está relacionada",
    "alternativa_a": "à concentração de trabalhadores com habilidades específicas em apenas um foco de atividade.",
