    "modulo_id": 6,
    "enunciado": "O processo de organização é pautado por alguns princípios ou elementos básicos, formulados por autores como Fayol e Weber. O número de subordinados pelos quais um gestor é responsável e que determina, no processo de organização, formatos mais verticais ou horizontais das estruturas organizacionais é conhecido como:",
