    "enunciado": "Sobre os critérios para a conceituação do Direito Administrativo, assinale a alternativa incorreta.",
    "alternativa_a": "Critério do Poder Executivo: o objeto do Direito Administrativo estaria relacionado à atuação, exclusiva, do Poder Executivo.",
    "alternativa_b": "Critério do Serviço Público: o objeto do Direito Administrativo envolveria a disciplina jurídica dos serviços públicos prestados.",
    "alternativa_c": "Critério das Relações Jurídicas: o Direito Administrativo seria o conjunto de regras disciplinadoras das relações entre a Administração e os administrados.",
