    "modulo_id": 9,
    "enunciado": "Acerca da Administração Pública e seus aspectos, assinale a alternativa correta.",
    "alternativa_a": "Aspecto Objetivo: conjunto de órgãos e entidades que integram a estrutura do Estado e tem como função satisfazer o interesse público, a vontade política governamental.",
