    "modulo_id": 9,
    "enunciado": "Flavius Junios, assíduo utilizador das redes sociais, postou o seguinte texto em um dos seus “stories”: “Essa entidade é também chamada de fundação governamental. Segue um regime misto, híbrido e sua criação deve ser autorizada por Lei.” De acordo com os preceitos administrativos, indique a qual “entidade” se referia o “blogueirinho” Flavius:",
