    "enunciado": "Ainda acerca da Lei Orgânica e o Estatuto da Polícia Civil do Estado do Rio Grande do Norte, assinale a alternativa correta.",
    "alternativa_a": "Fica assegurada à Polícia Civil autonomia administrativa, sendo que a gestão orçamentária e financeira dos recursos alocados em seu orçamento dependem de decreto a ser expedido pelo Governador do Estado.",
